-- Cultos y Órganos de Gobierno pasan del texto de partida a una página por bloques.
--
-- Se conserva lo que ya decían (las celebraciones del año, los cargos de la
-- Junta) con iconos y en dos columnas, y se añade una cita del Evangelio, las
-- próximas citas de la Agenda, preguntas frecuentes y la llamada a escribir.
-- Sale el «Quinario al Santo Cristo»: el Grupo tiene una sola titular; entra el
-- Rosario vespertino de octubre. No se publican nombres de la Junta ni horarios
-- que el Grupo no haya dado.
--
-- Solo se sustituye la página que sigue con el texto de partida: si alguien ya
-- la ha editado en el CMS, se queda como está.

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Cultos","subtitulo":"Celebraciones y devociones en honor a nuestra Sagrada Titular.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>La vida espiritual del Grupo Parroquial se alimenta de los cultos que celebramos a lo largo del año. Son ocasiones para rezar juntos, para venerar a Nuestra Señora de los Desamparados y para el encuentro fraterno entre los hermanos.</p><p>Todos se celebran en la parroquia de Santa María Goretti y están abiertos a cualquiera que quiera acompañarnos, sea o no hermano.</p>"},{"tipo":"tarjetas","titulo":"Celebraciones del año","presentacion":{"columnas":"2","estilo":"contorno","orientacion":"horizontal","alineacion":"izquierda"},"tarjetas":[{"titulo":"Cultos mensuales","descripcion":"Celebración de la Eucaristía y momentos de oración fraterna con los hermanos, generalmente el primer sábado de mes.","enlace":"","icono":"calendario"},{"titulo":"Triduo a la Sagrada Titular","descripcion":"Tres días de culto en noviembre en honor a Nuestra Señora de los Desamparados, con predicación y celebración de los sacramentos.","enlace":"/desamparados","icono":"sol"},{"titulo":"Besamanos de la Virgen","descripcion":"Solemne besamanos durante el cual los devotos y hermanos pueden venerar de cerca la imagen de la Sagrada Titular.","enlace":"","icono":"corazon"},{"titulo":"Rosario vespertino","descripcion":"En octubre, el mes del Rosario, la Virgen sale por las calles del barrio mientras se rezan sus misterios.","enlace":"","icono":"flor"},{"titulo":"Sábado de Pasión","descripcion":"Nuestra salida procesional por las calles de Málaga, momento culminante del año cofrade del Grupo Parroquial.","enlace":"/sabado-de-pasion","icono":"estrella"},{"titulo":"Cultos de Navidad y Semana Santa","descripcion":"Celebraciones especiales que marcan los grandes momentos litúrgicos del año en la vida parroquial y cofrade.","enlace":"","icono":"iglesia"}]},{"tipo":"cita","titulo":"","presentacion":{"estilo":"franja","alineacion":"centro"},"texto":"Desde ahora me felicitarán todas las generaciones, porque el Poderoso ha hecho obras grandes por mí.","autor":"María","fuente":"Evangelio según san Lucas, 1, 48-49"},{"tipo":"listado","titulo":"Próximas citas","fuente":"agenda-proxima","presentacion":{"disposicion":"lista"}},{"tipo":"preguntas","titulo":"Preguntas frecuentes","preguntas":[{"pregunta":"¿Tengo que ser hermano para ir?","respuesta":"No. Los cultos están abiertos a todos: hermanos, devotos, vecinos y cualquiera que quiera acercarse."},{"pregunta":"¿Dónde se celebran?","respuesta":"En la parroquia de Santa María Goretti, nuestra sede. En la página de la parroquia tienes la dirección, el mapa y el horario de misas."},{"pregunta":"¿Cómo me entero de las fechas?","respuesta":"Las publicamos en la Agenda con su día, hora y lugar. Desde allí puedes añadir cada acto a tu calendario o suscribirte para que te lleguen solos."}]},{"tipo":"botones","titulo":"","presentacion":{"alineacion":"centro"},"botones":[{"texto":"Ver la agenda","enlace":"/agenda","estilo":"principal"},{"texto":"La parroquia","enlace":"/parroquia-pasionistas","estilo":"secundario"}]}]}'
WHERE `slug` = 'cultos' AND `datos` LIKE '%Quinario al Santo Cristo%';

UPDATE `ContenidoPagina` SET `datos` = '{"cabecera":{"titulo":"Órganos de Gobierno","subtitulo":"Junta de Gobierno y órganos de dirección de la corporación.","foto":"","fotoAlt":""},"bloques":[{"tipo":"texto","titulo":"","html":"<p>La Junta de Gobierno es el órgano colegiado encargado de la dirección, administración y representación del Grupo Parroquial. Desde sus distintas vocalías, trabaja unida al servicio de los hermanos y de la misión evangelizadora de la corporación.</p><p>Gobernar un grupo parroquial es, sobre todo, servir: cada cargo es una tarea que alguien asume por amor a la Virgen y a sus hermanos, en comunión con la parroquia.</p>"},{"tipo":"tarjetas","titulo":"Cargos de la Junta de Gobierno","presentacion":{"columnas":"2","estilo":"contorno","orientacion":"horizontal","alineacion":"izquierda"},"tarjetas":[{"titulo":"Hermano Mayor","descripcion":"Máximo responsable de la corporación, representa al Grupo Parroquial y dirige sus actuaciones con autoridad espiritual y gobierno.","enlace":"","icono":"estrella"},{"titulo":"Teniente Hermano Mayor","descripcion":"Segunda autoridad del Grupo Parroquial, asiste al Hermano Mayor en sus funciones y le sustituye en caso de ausencia.","enlace":"","icono":"grupo"},{"titulo":"Secretario","descripcion":"Gestiona la documentación, actas de reuniones, correspondencia oficial y archivo histórico de la corporación.","enlace":"","icono":"libro"},{"titulo":"Tesorero","descripcion":"Administra los bienes económicos del Grupo Parroquial, elabora los presupuestos y controla los recursos con transparencia.","enlace":"","icono":"info"},{"titulo":"Vocal de Cultos","descripcion":"Coordina la celebración de los cultos, ceremonias y actos de devoción en honor a nuestra Sagrada Titular.","enlace":"/cultos","icono":"iglesia"},{"titulo":"Vocal de Caridad","descripcion":"Impulsa las obras asistenciales y canaliza la ayuda social del Grupo Parroquial hacia quienes más lo necesitan.","enlace":"/nuestros-fines/caridad","icono":"manos"},{"titulo":"Vocal de Formación","descripcion":"Promueve la educación en la fe, los encuentros formativos y la transmisión de los valores de la corporación.","enlace":"/nuestros-fines/formacion","icono":"libro"}]},{"tipo":"cita","titulo":"","presentacion":{"estilo":"franja","alineacion":"centro"},"texto":"El que quiera ser grande entre vosotros, que sea vuestro servidor.","autor":"Jesús","fuente":"Evangelio según san Mateo, 20, 26"},{"tipo":"llamada","titulo":"","texto":"¿Quieres hacer llegar algo a la Junta de Gobierno?","boton":"Escríbenos","enlace":"/contacto"}]}'
WHERE `slug` = 'organos-de-gobierno' AND `datos` LIKE '%Desde sus distintas vocales%';
